59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    /**
112	     * Rejects an owner payload that is missing or blank in any of the required fields
113	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
114	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
115	     * value as present; this guard closes that gap so a blank in any required field is
116	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
117	     * the name of each offending field.
118	     */
119	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto) {
120	        List<String> missing = new ArrayList<>();
121	        if (isBlank(ownerFieldsDto.getFirstName())) {
122	            missing.add("firstName");
123	        }
124	        if (isBlank(ownerFieldsDto.getLastName())) {
125	            missing.add("lastName");
126	        }
127	        if (isBlank(ownerFieldsDto.getAddress())) {
128	            missing.add("address");
129	        }
130	        if (isBlank(ownerFieldsDto.getCity())) {
131	            missing.add("city");
132	        }
133	        if (isBlank(ownerFieldsDto.getTelephone())) {
134	            missing.add("telephone");
135	        }
136	        if (!missing.isEmpty()) {
137	            throw new MissingOwnerFieldsException(missing);
138	        }
139	    }
140	
141	    private static boolean isBlank(String value) {
142	        return value == null || value.isBlank();
143	    }
144	
145	    /**
146	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
147	     */
148	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
149	
150	    /**
151	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
152	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
153	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
154	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
155	     * stored as '+61412345678'. A value that cannot form a valid E.164 number is rejected via
156	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
157	     */
158	    private static String normalizeTelephone(String telephone) {
159	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
160	        String e164;
161	        if (cleaned.startsWith("+")) {
162	            e164 = cleaned;
163	        } else {
164	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
165	            e164 = "+61" + national;
166	        }
167	        if (!E164_PATTERN.matcher(e164).matches()) {
168	            throw new InvalidTelephoneException(telephone);
169	        }
170	        return e164;
171	    }
172	
173	    /**
174	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
175	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
176	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
177	     */
178	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
179	
180	    /**
181	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
182	     * optional). When present it must be a syntactically valid address; a valid value is
183	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
184	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
185	     */
186	    private static String normalizeEmail(String email) {
187	        if (email == null) {
188	            return null;
189	        }
190	        if (!EMAIL_PATTERN.matcher(email).matches()) {
191	            throw new InvalidEmailException(email);
192	        }
193	        return email.toLowerCase(Locale.ROOT);
194	    }
195	
196	    /**
197	     * Rejects a create whose normalized telephone is already used by another owner. Each
198	     * existing owner's stored telephone is reduced to its E.164 form the same way {@code
199	     * normalizeTelephone} does, so the comparison is on the canonical E.164 value regardless of
200	     * the format each was originally entered in. An existing value that cannot form a valid E.164
201	     * number is skipped rather than colliding. A match is reported via
202	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
203	     */
204	    private void rejectDuplicateTelephone(String normalizedTelephone) {
205	        for (Owner existing : this.clinicService.findAllOwners()) {
206	            String existingE164;
207	            try {
208	                existingE164 = normalizeTelephone(existing.getTelephone());
209	            } catch (InvalidTelephoneException ex) {
210	                continue;
211	            }
212	            if (normalizedTelephone.equals(existingE164)) {
213	                throw new DuplicateTelephoneException(normalizedTelephone);
214	            }
215	        }
216	    }
217	
218	    /**
219	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
220	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
221	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
222	     * spacing do not defeat the duplicate-household check.
223	     */
224	    private static String collapse(String value) {
225	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
226	    }
227	
228	    /**
229	     * Rejects a create that would place a second owner in the same household as an existing one -
230	     * i.e. another owner already has the same {@code lastName} and the same {@code address},
231	     * compared case-insensitively with collapsed whitespace. The caller can opt in to sharing a
232	     * household by setting {@code sharesHousehold} true, in which case this check is skipped. A
233	     * match is reported via {@link DuplicateHouseholdException}, which the exception handler
234	     * translates to a 409.
235	     */
236	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
237	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
238	            return;
239	        }
240	        String lastName = collapse(ownerFieldsDto.getLastName());
241	        String address = collapse(ownerFieldsDto.getAddress());
242	        for (Owner existing : this.clinicService.findAllOwners()) {
243	            if (lastName.equals(collapse(existing.getLastName()))
244	                && address.equals(collapse(existing.getAddress()))) {
245	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
246	            }
247	        }
248	    }
249	
250	    /**
251	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}
252	     * where {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN}
253	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners
254	     * (e.g. {@code 'SMI-0007'}).
255	     */
256	    private String nextCustomerCode(String lastName) {
257	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
258	        int sequence = this.clinicService.findAllOwners().size() + 1;
259	        return String.format("%s-%04d", last3, sequence);
260	    }
261	
262	    /**
263	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
264	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
265	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
266	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
267	     * receives the identical, non-blank identifier without needing to read any other owner's value.
268	     */
269	    private static String householdIdFor(String lastName, String address) {
270	        String key = collapse(lastName) + "\n" + collapse(address);
271	        try {
272	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
273	            StringBuilder sb = new StringBuilder(32);
274	            for (int i = 0; i < 8; i++) {
275	                sb.append(String.format("%02X", digest[i]));
276	            }
277	            return sb.toString();
278	        } catch (NoSuchAlgorithmException ex) {
279	            throw new IllegalStateException("SHA-256 not available", ex);
280	        }
281	    }
282	
283	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
284	    @Override
285	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
286	        rejectMissingOrBlankFields(ownerFieldsDto);
287	        rejectDuplicateHousehold(ownerFieldsDto);
288	        HttpHeaders headers = new HttpHeaders();
289	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
290	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
291	        rejectDuplicateTelephone(normalizedTelephone);
292	        owner.setTelephone(normalizedTelephone);
293	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
294	        if (owner.getRegistrationDate() == null) {
295	            owner.setRegistrationDate(LocalDate.now());
296	        }
297	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
298	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
299	        this.clinicService.saveOwner(owner);
300	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
301	        headers.setLocation(UriComponentsBuilder.newInstance()
302	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
303	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
304	    }
305	
306	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
307	    @Override
308	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
309	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
310	        if (currentOwner == null) {
311	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
312	        }
313	        currentOwner.setAddress(ownerFieldsDto.getAddress());
314	        currentOwner.setCity(ownerFieldsDto.getCity());
315	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
316	        currentOwner.setLastName(ownerFieldsDto.getLastName());
317	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
318	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
319	        this.clinicService.saveOwner(currentOwner);
320	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
321	    }
322	
323	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
324	    @Transactional
325	    @Override
326	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
327	        Owner owner = this.clinicService.findOwnerById(ownerId);
328	        if (owner == null) {
329	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
330	        }
331	        this.clinicService.deleteOwner(owner);
332	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
333	    }
334	
335	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
336	    @Override
337	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
338	        Owner owner = this.clinicService.findOwnerById(ownerId);
339	        if (owner == null) {
340	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
341	        }
342	        HttpHeaders headers = new HttpHeaders();
343	        Pet pet = petMapper.toPet(petFieldsDto);
344	        owner.setId(ownerId);
345	        pet.setOwner(owner);
346	        pet.getType().setName(null);
347	        this.clinicService.savePet(pet);
348	        PetDto petDto = petMapper.toPetDto(pet);
349	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
350	            .buildAndExpand(pet.getId()).toUri());
351	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
352	    }
353	
354	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
355	    @Override
356	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
357	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
358	        if (currentOwner != null) {
359	            Pet currentPet = this.clinicService.findPetById(petId);
360	            if (currentPet != null) {
361	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
362	                currentPet.setName(petFieldsDto.getName());
363	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
364	                this.clinicService.savePet(currentPet);
365	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
366	            }
367	        }
368	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
369	    }
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Override
373	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
374	        HttpHeaders headers = new HttpHeaders();
375	        Visit visit = visitMapper.toVisit(visitFieldsDto);
376	        Pet pet = new Pet();
377	        pet.setId(petId);
378	        visit.setPet(pet);
379	        this.clinicService.saveVisit(visit);
380	        VisitDto visitDto = visitMapper.toVisitDto(visit);
381	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
382	            .buildAndExpand(visit.getId()).toUri());
383	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
384	    }
385	
386	
387	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
388	    @Override
389	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
390	        Owner owner = this.clinicService.findOwnerById(ownerId);
391	        if (owner != null) {
392	            Pet pet = owner.getPet(petId);
393	            if (pet != null) {
394	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
395	            }
396	        }
397	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	    }
399	}
